%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% AAE 590SC
% Path Integral Control on Lie Groups
% Author: Nyssa Guha, Travis Hastreiter
% Created On: 8 December, 2025
% Description: Lie group path integral control of a rigid body's
% 3D orientation with sun cone chance constraint
% Most Recent Change: 12 December, 2025
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

G = SO3_RotationMatrix();

z = zeros(G.dim);
I = eye(G.dim);

tolerances = odeset(RelTol=1e-6, AbsTol=1e-6);

%% Define Noise
noise_delta_t = 1e-2;

w = @(n) randn([G.dim, n]);

sigma_dist = 0.05; % [kg m2 / s2]
sigma = [2 * sigma_dist, 0, 0; 0, sigma_dist, 0; 0, 0, sigma_dist]; % need to double check the sqrt(delta t) part

%% Create Dynamics 
moment_of_inertia = diag([1, 1.11, 1.3]);
J_b = moment_of_inertia; % Generalized inertia

B_map = @(x) I;
[f, B] = Euler_Poincare_matrices(SO3_RotationMatrix(), J_b, B_map);

f_with_control = @(t, x, u) [z, I; z, z] * x + [z; B(t, x)] * u;
control_delta_t = 0.01;
t_k = 0:control_delta_t:2;
u_k = 0 * ones([G.dim, numel(t_k) - 1]);

R = eye(G.dim);
S_g = 1.6e9 * eye(G.dim);
S_twist = 8e8 * eye(G.dim);

%% Define Initial Condition and Target
g0 = SO3_RotationMatrix(angle2dcm(deg2rad(-15), deg2rad(0), deg2rad(0))); % Initial DCM
twist0 = [0; 0; 0]; % Initial angular velocity

gtarg = SO3_RotationMatrix(angle2dcm(50, deg2rad(120), deg2rad(240))'); % Target DCM
twisttarg = zeros([3, 1]);

%%\
% Define initial state covariance
sigma_xhat0 = [1e-2; ... % _x
               1e-2; ... % _y
               1e-2]; ... % _z
P0 = diag(sigma_xhat0 .^ 2);

P_k = zeros([3, 3, numel(t_k)]);
P_k(:, :, 1) = P0;
X0 = chol(P0);

filter.A_k = G.Ad(G.Exp(twist0 * control_delta_t));
filter.G_k = B(0, g0) * sigma / sqrt(noise_delta_t) * control_delta_t;
for k = 1 : numel(t_k) - 1
    P_k(:, :, k + 1) = filter.A_k * P_k(:, :, k) * filter.A_k' ...
                          + filter.G_k * filter.G_k';
end

P_fail = 0.01;
backoff_coef = sqrt(chi2inv(1 - P_fail, 1));

%% Set up constraint
logistic = @(x) 1 ./ (1 + exp(-2000*x)); % Smooth out penalty

objective_penalty = 1e7;
cone_angle = 30; % [deg]
sun_dcm = angle2dcm(-1.4, 0.8, 1.2);
sun_direction = sun_dcm * [0; 0; 1];
%sensor_direction_body = angle2dcm(-1, 0.2, -2) * [0; 0; 1];
sensor_direction_body = angle2dcm(0, 0, 0) * [0; 1; 0];
sensor_direction_inertial = gtarg.element * sensor_direction_body;

alpha = @(g, X) X' * g.element' * [-(sun_direction(2) * sensor_direction_inertial(3) - sun_direction(3) * sensor_direction_inertial(2)); ...
                                     sun_direction(1) * sensor_direction_inertial(3) - sun_direction(3) * sensor_direction_inertial(1); ...
                                   -(sun_direction(1) * sensor_direction_inertial(2) - sun_direction(2) * sensor_direction_inertial(1))];
alpha_hat = @(g, X) alpha(g, X) / norm(alpha(g, X));
sun_chance_constraint = @(g, X) -cosd(cone_angle) + sun_direction' * g.rplus(-backoff_coef * X * alpha_hat(g, X)).element * sensor_direction_body;
chance_constrained_state_running_cost = @(g, twist, X) objective_penalty * logistic(sun_chance_constraint(g, X));

sun_constraint = @(g, twist) objective_penalty * logistic(-cosd(cone_angle) + sun_direction' * g.element * sensor_direction_body);


%% Run Monte Carlo
m = 40;

g_k = createArray(numel(t_k), m, class(g0)); % array of group elements
twist_k = zeros(G.dim, numel(t_k), m); % array of twists (body velocities)
P_k = zeros(G.dim, G.dim, numel(t_k), m);
P_k(:, :, 1, :) = repmat(P0, 1, 1, 1, m);
X_k = zeros(G.dim, G.dim, numel(t_k), m);
X_k(:, :, 1, :) = repmat(chol(P0), 1, 1, 1, m);
delta_u = zeros([G.dim, numel(t_k) - 1, m]);
w_k = zeros([G.dim, numel(t_k) - 1, m]);


iterations = 120;
lambda_matrix = sigma * sigma' * R;
lambda = lambda_matrix(1) * 1;
average_cost = zeros([1, iterations]);
cost_t = zeros([numel(t_k) - 1, m, iterations]);
cost_exit = zeros([m, iterations]);
for j = 1 : iterations %[output:group:3cb3b459]
    %[g_k(:, 1), twist_k(:, :, 1), delta_u(:, :, 1), w_k(:,:,1)] = one_step_euler_maruyama_lie_group(f, B, g0, twist0, u_k, t_k, sigma*0);
    %[~, g_k(:, 1), twist_k(:, :, 1), ~, delta_u(:, :, 1)] = sode45_liegroup(u_k, sigma*0, w, t_k, noise_delta_t, g0, twist0, J_b, tolerances);
    parfor i = 1 : m
        P_k_i = zeros([3, 3, numel(t_k)]);
        P_k_i(:, :, 1) = P0;
        X_k_i = zeros([3, 3, numel(t_k)]);
        X_k_i(:, :, 1) = X0;
        %[~, g_k(:, i), twist_k(:, :, i), ~, delta_u(:, :, i)] = sode45_liegroup(u_k, sigma, w, t_k, noise_delta_t, g0, twist0, J_b, tolerances);
        [g_k_i, twist_k_i, delta_u(:, :, i), w_k(:,:,i)] = one_step_euler_maruyama_lie_group(f, B, g0, twist0, u_k, t_k, sigma);
        for k = 1 : numel(t_k) - 1
            A_k = G.Ad(G.Exp(twist_k_i(:, k) * control_delta_t));
            G_k = B(t_k(k), g_k_i(k)) * sigma / sqrt(noise_delta_t) * control_delta_t;
            
            P_k_i(:, :, k + 1) = A_k * P_k_i(:, :, k) * A_k' + G_k * G_k';        
            X_k_i(:, :, k + 1) = chol(P_k_i(:, :, k + 1));
        end

        g_k(:, i) = g_k_i;
        twist_k(:, :, i) = twist_k_i;
        P_k(:, :, :, i) = P_k_i;
        X_k(:, :, :, i) = X_k_i;
    end
    
    %[L, cost_t(:, :, j), cost_exit(:, j)] = liegroup_cost(g_k, twist_k, u_k + delta_u, control_delta_t, gtarg, twisttarg, R, S_g = S_g, S_twist = S_twist);
    [L, cost_t(:, :, j), cost_exit(:, j)] = liegroup_cost(g_k, twist_k, u_k + delta_u, control_delta_t, gtarg, twisttarg, R, S_g = S_g, S_twist = S_twist, state_running_cost = chance_constrained_state_running_cost, X_k = X_k);

%    [u_k, D_k] = liegroup_update(g_k, u_k, twist_k, pagemtimes(sigma, w_k), f, B, R, L, t_k, lambda);
    u_km1 = u_k;
    S_k = cumsum(L, 1, "reverse");
    [u_k, D_k] = liegroup_update(g_k, u_k, twist_k, delta_u, f, B, R, S_k, t_k, lambda);

    average_cost(j) = min(sum(L .* control_delta_t, 1), [], "all");
    average_cost(j) %[output:1ab92ebb] %[output:338890e7] %[output:29f2eed6] %[output:5a933a6f] %[output:1dd7975c] %[output:82715103] %[output:58e0a62c] %[output:7afbe239] %[output:457cd79b] %[output:4a86d908] %[output:728234cc] %[output:2d449e68] %[output:78047e6a] %[output:8029cde0] %[output:005cc2a4] %[output:44a278b7] %[output:0a2390b2] %[output:9ea1edc7] %[output:45429616] %[output:7a5f456a] %[output:86f8cc78] %[output:6ddf9d02] %[output:806cf3cb] %[output:27b3fb44] %[output:9418f9a2] %[output:4d99d2fd] %[output:7c110946] %[output:98fd9a1d] %[output:69a3071e] %[output:7d55503c] %[output:330eb9d8] %[output:4b0f7eb4] %[output:45e2875e] %[output:75f14465] %[output:6c727575] %[output:28e08948] %[output:45ff0324] %[output:01ef4b27] %[output:7341937f] %[output:5e3236dd] %[output:49b0d37f] %[output:8278de17] %[output:298bac11] %[output:68150a08] %[output:26f45a15] %[output:9855deb8] %[output:3f006801] %[output:2cb3dfad] %[output:4a94dcb8] %[output:3a1c0a90] %[output:933325ee] %[output:138ad494] %[output:65f3eae8] %[output:6720df19] %[output:1293b3ca] %[output:23ebbaf1] %[output:54c4b853] %[output:63f16703] %[output:2b8070a4] %[output:95a29709] %[output:4e732028] %[output:7576c8eb] %[output:25126d6c] %[output:31f1612a] %[output:8885ea6a] %[output:74dd6977] %[output:24f9f48e] %[output:81e78838] %[output:18b9dadb] %[output:10f5f2ec] %[output:3a58d294] %[output:4280d90a] %[output:719179dc] %[output:75cbb597] %[output:4967524d] %[output:1103510b] %[output:0524199a] %[output:3373f623] %[output:103c4294] %[output:44abc742] %[output:4f3d1f67] %[output:58eb549f] %[output:66193066] %[output:8991855d] %[output:824eaeab] %[output:9495f65d] %[output:8bc0c961] %[output:078793f4] %[output:4af4f910] %[output:167f5c74] %[output:1f91b63a] %[output:617978c8] %[output:10c21038] %[output:5ddba9f0] %[output:04fe94cb] %[output:8010c11f] %[output:8a84cb98] %[output:591406c9] %[output:303c3f5e] %[output:1d982407] %[output:36395e9c] %[output:5920ac28] %[output:36b3c109] %[output:79a65f13] %[output:54a7747f] %[output:37ff6f9c] %[output:7e33a7fc] %[output:3b39999d] %[output:5269fbcb] %[output:41e74464] %[output:43fcc00e] %[output:50fe6b77] %[output:074e9032] %[output:8b962ffb] %[output:4dca032a] %[output:22829632] %[output:05db3408] %[output:3c9fd03a] %[output:5e393bfe] %[output:9d857344]

    if mod(j, 20) == 0 || j == 1

        figure %[output:07a4c22a] %[output:2426612c] %[output:85d65b36] %[output:836ccb61] %[output:4fb382eb] %[output:73374a9c] %[output:1f82b123]
        tiledlayout(3, 12) %[output:07a4c22a] %[output:2426612c] %[output:85d65b36] %[output:836ccb61] %[output:4fb382eb] %[output:73374a9c] %[output:1f82b123]
        
        quaternions = SO3_RotationMatrix_to_quaternions(g_k(2:end, :));
        quaternion_target = SO3_RotationMatrix_to_quaternions(gtarg);
        colormap(jet);  
        
        nexttile([1,3])
        scatter(repmat(t_k(2:end), 1, m), squeeze(quaternions(4, :)), [], L(:), "filled"); hold on
        grid on
%         alpha(D_k(:));
         scatter(t_k(end), quaternion_target(4), 10, 'r');
        colorbar
        xlabel("Time [s]")
        ylabel("q_w")
        title("")
        nexttile([1,3])
        scatter(repmat(t_k(2:end), 1, m), squeeze(quaternions(1, :)), [], L(:), "filled"); hold on
        grid on
%         alpha(D_k(:));
        scatter(t_k(end), quaternion_target(1), 10, 'r');
        colorbar
        xlabel("Time [s]")
        ylabel("q_x")
        title("")
        nexttile([1,3])
        scatter(repmat(t_k(2:end), 1, m), squeeze(quaternions(2, :)), [], L(:), "filled"); hold on
        grid on
%         alpha(D_k(:));
        scatter(t_k(end), quaternion_target(2), 10, 'r');
        colorbar
        xlabel("Time [s]")
        ylabel("q_y")
        title("")
        nexttile([1,3])
        scatter(repmat(t_k(2:end), 1, m), squeeze(quaternions(3, :)), [], L(:), "filled"); hold on
        grid on
%         alpha(D_k(:));
        scatter(t_k(end), quaternion_target(3), 10, 'r');
        colorbar
        xlabel("Time [s]")
        ylabel("q_z")
        title("")
        sgtitle(sprintf("Unit Quaternions: Iteration %d, avg cost %.3f", j, average_cost(j)))

        twist_k_Nu = twist_k(:, 2:end, :);

        nexttile([1,4])
        scatter(repmat(t_k(2:end), 1, m), squeeze(twist_k_Nu(1, :)), [], L(:), "filled"); hold on
%         alpha(D_k(:));
        grid on
        colorbar
        xlabel("Time [s]")
        ylabel("w_x")
        title("")
        nexttile([1,4])
        scatter(repmat(t_k(2:end), 1, m), squeeze(twist_k_Nu(2, :)), [], L(:), "filled"); hold on
        grid on
%         alpha(D_k(:));
        colorbar
        xlabel("Time [s]")
        ylabel("w_y")
        title("")
        nexttile([1,4])
        scatter(repmat(t_k(2:end), 1, m), squeeze(twist_k_Nu(3, :)), [], L(:), "filled"); hold on
        grid on
%         alpha(D_k(:));
        colorbar
        xlabel("Time [s]")
        ylabel("w_z")
        title("")

        % Control
        u_k_m = u_km1 + delta_u;

        nexttile([1,4])
        scatter(repmat(t_k(2:end), 1, m), squeeze(u_k_m(1, :)), [], L(:), "filled"); hold on
        scatter(t_k(2:end), squeeze(u_k(1, :)), 50, "black", "square"); hold on
        grid on
%         alpha(D_k(:));
        colorbar
        xlabel("Time [s]")
        ylabel("u_x")
        title("")
        nexttile([1,4])
        scatter(repmat(t_k(2:end), 1, m), squeeze(u_k_m(2, :)), [], L(:), "filled"); hold on
        scatter(t_k(2:end), squeeze(u_k(2, :)), 50, "black", "square"); hold on
        grid on
%         alpha(D_k(:));
        colorbar
        xlabel("Time [s]")
        ylabel("u_y")
        title("")
        nexttile([1,4])
        scatter(repmat(t_k(2:end), 1, m), squeeze(u_k_m(3, :)), [], L(:), "filled"); hold on
        scatter(t_k(2:end), squeeze(u_k(3, :)), 50, "black", "square"); hold on
        grid on
%         alpha(D_k(:));
        colorbar
        xlabel("Time [s]")
        ylabel("u_z")
        title("")
    end
end %[output:group:3cb3b459]


%% Time Histories
sigma_dist = 0.05; % [kg m2 / s2]
sigma = [2 * sigma_dist, 0, 0; 0, 1 * sigma_dist, 0; 0, 0, 1 * sigma_dist]; % need to double check the sqrt(delta t) part

m = 100;

g_k = createArray(numel(t_k), m, class(g0)); % array of group elements
twist_k = zeros(G.dim, numel(t_k), m); % array of twists (body velocities)
delta_u = zeros([G.dim, numel(t_k) - 1, m]);
w_k = zeros([G.dim, numel(t_k) - 1, m]);

parfor i = 1 : m
    g0_i = g0.sample_right_gaussian(P0);
    %[g_k(:, i), twist_k(:, :, i), delta_u(:, :, i), w_k(:,:,i)] = one_step_euler_maruyama_lie_group(f, B, g0, twist0, u_k, t_k, sigma);
    [~, g_k(:, i), twist_k(:, :, i), ~, delta_u(:, :, i)] = sode45_liegroup(u_k, sigma, w, t_k, noise_delta_t, g0_i, twist0, J_b, tolerances);
end
%[g_k_nom, twist_k_nom, delta_u_nom] = one_step_euler_maruyama_lie_group(f, B, g0, twist0, u_k, t_k, sigma*0);
[~, g_k_nom, twist_k_nom, ~, delta_u_nom] = sode45_liegroup(u_k, sigma*0, @(n) zeros([G.dim, n]), t_k, noise_delta_t, g0, twist0, J_b, tolerances);

%%\
lerror = zeros([3, numel(t_k), m]);
for i = 1 : m
    for k = 1 : numel(t_k)
        lerror(:, k, i) = g_k_nom(k).left_invariant_error(g_k(k, i)); 
    end
end

for k = 1 : numel(t_k) - 1
    filter.A_k = G.Ad(G.Exp(twist_k_nom(:, k) * control_delta_t));
    filter.G_k = B(t_k(k), g_k_nom(k)) * sigma / sqrt(noise_delta_t) * control_delta_t;
    
    P_k(:, :, k + 1) = filter.A_k * P_k(:, :, k) * filter.A_k' ...
                          + filter.G_k * filter.G_k';
end

error_std = zeros([3, numel(t_k)]);
for k = 1 : numel(t_k)
    error_std(:, k) = rad2deg(diag(chol(P_k(:, :, k)))) * backoff_coef;
end
%%\

tiledlayout(1, 3) %[output:1f82b123]
nexttile %[output:1f82b123]
plot(t_k, rad2deg((squeeze(lerror(1, :, :)))), Color = [192, 192, 192] / 256); hold on  %[output:1f82b123]
plot(t_k, error_std(1, :), Color = "m") %[output:1f82b123]
plot(t_k, -error_std(1, :), Color = "m") %[output:1f82b123]
grid on %[output:1f82b123]
nexttile %[output:1f82b123]
