plot(t_k, -error_std(2, :), Color = "m") %[output:1f82b123]
grid on %[output:1f82b123]
nexttile %[output:1f82b123]
plot(t_k, rad2deg((squeeze(lerror(3, :, :)))), Color = [192, 192, 192] / 256); hold on %[output:1f82b123]
plot(t_k, error_std(3, :), Color = "m") %[output:1f82b123]
plot(t_k, -error_std(3, :), Color = "m") %[output:1f82b123]
grid on %[output:1f82b123]


