title("") %[output:519cefcd]
nexttile([1,4]) %[output:519cefcd]
scatter(repmat(t_k, 1, m), squeeze(twist_k(3, :)), [], [192, 192, 192] / 256, "filled", HandleVisibility="off"); hold on %[output:519cefcd]
grid on %[output:519cefcd]
%         alpha(D_k(:));
scatter(t_k, twist_k_nom(3, :), 10, 'r'); %[output:519cefcd]
scatter(t_k(end), twisttarg(3), 10, 'k'); %[output:519cefcd]
xlabel("Time [s]") %[output:519cefcd]
ylabel("w_x") %[output:519cefcd]
title("") %[output:519cefcd]

% Control
u_k_m = u_k + delta_u;
nexttile([1,4]) %[output:519cefcd]
scatter(repmat(t_k(2:end), 1, m), squeeze(u_k_m(1, :)), [], [192, 192, 192] / 256, "filled", HandleVisibility="off"); hold on %[output:519cefcd]
grid on %[output:519cefcd]
%         alpha(D_k(:));
scatter(t_k(2:end), u_k(1, :), 10, 'r'); %[output:519cefcd]
xlabel("Time [s]") %[output:519cefcd]
ylabel("u_x") %[output:519cefcd]
title("") %[output:519cefcd]
nexttile([1,4]) %[output:519cefcd]
scatter(repmat(t_k(2:end), 1, m), squeeze(u_k_m(2, :)), [], [192, 192, 192] / 256, "filled", HandleVisibility="off"); hold on %[output:519cefcd]
grid on %[output:519cefcd]
%         alpha(D_k(:));
scatter(t_k(2:end), u_k(2, :), 10, 'r'); %[output:519cefcd]
xlabel("Time [s]") %[output:519cefcd]
ylabel("u_y") %[output:519cefcd]
title("") %[output:519cefcd]
nexttile([1,4]) %[output:519cefcd]
scatter(repmat(t_k(2:end), 1, m), squeeze(u_k_m(3, :)), [], [192, 192, 192] / 256, "filled", HandleVisibility="off"); hold on %[output:519cefcd]
grid on %[output:519cefcd]
%         alpha(D_k(:));
scatter(t_k(2:end), u_k(3, :), 10, 'r'); %[output:519cefcd]
xlabel("Time [s]") %[output:519cefcd]
ylabel("u_z") %[output:519cefcd]
title("") %[output:519cefcd]


%% Iterations
figure %[output:336fd063]
plot(average_cost); hold on %[output:336fd063]
scatter(1 : iterations, squeeze(sum(cost_t, 1)), MarkerFaceColor = [192, 192, 192] / 256, MarkerEdgeColor="none", HandleVisibility="off") %[output:336fd063]
scatter(1 : iterations, cost_exit, MarkerFaceColor = [192, 192, 192] / 256, MarkerEdgeColor="none", HandleVisibility="off") %[output:336fd063]
plot(mean(squeeze(sum(cost_t, 1)), 1), Color = "b"); %[output:336fd063]
plot(mean(cost_exit, 1), Color = "r"); %[output:336fd063]
grid on %[output:336fd063]
legend("Total Cost", "Path Cost", "Exit Cost") %[output:336fd063]
xlabel("Iteration") %[output:336fd063]
ylabel("Cost") %[output:336fd063]
title("Cost vs Iteration") %[output:336fd063]
yscale("log") %[output:336fd063]

%%\
figure %[output:19434226]
plot_basis(g0.element, "i", ":", scale = 1); %[output:19434226]
for i = 1 : 20 : numel(t_k)
    plot_basis(g_k_nom(i).element, "", "-", scale = 0.7); %[output:19434226]
    sensor_direction_inertial = g_k_nom(i).element * sensor_direction_body;
    quiver3(0, 0, 0, sensor_direction_inertial(1), sensor_direction_inertial(2), sensor_direction_inertial(3), Color = "m", DisplayName="", AutoScaleFactor=1, HandleVisibility="off")
    for j = 1 : m
        sensor_direction_inertial = g_k(i, j).element * sensor_direction_body;
        quiver3(0, 0, 0, sensor_direction_inertial(1), sensor_direction_inertial(2), sensor_direction_inertial(3), Color = "cyan", DisplayName="", AutoScaleFactor=0.8, HandleVisibility="off")
    end
end
plot_basis(gtarg.element, "f", "--", scale = 1) %[output:27ae0f3b] %[output:19434226]
quiver3(0, 0, 0, sensor_direction_inertial(1), sensor_direction_inertial(2), sensor_direction_inertial(3), DisplayName="sensor", AutoScaleFactor=1, Color = "m") %[output:19434226]
quiver3(0, 0, 0, sun_direction(1), sun_direction(2), sun_direction(3), DisplayName="sun", AutoScaleFactor=1) %[output:19434226]
[X,Y,Z]=cylinder([0 deg2rad(cone_angle)], 50);
Z = Z * 0.9;
%axis([0 1,-1 1,-.5 .5])
M=[sun_dcm, zeros([3, 1]); zeros([1, 3]), 1];
h=surf(X,Y,Z,'Parent',hgtransform('Matrix',M),'LineStyle','none','FaceAlpha',0.4); %[output:19434226]
view([30,35]) %[output:19434226]
grid on %[output:19434226]
light %[output:19434226]
axis equal %[output:19434226]
xlim([-1, 1]) %[output:19434226]
ylim([-1, 1]) %[output:19434226]
zlim([-1, 1]) %[output:19434226]

